const distributionMap: Record<string, TexturedDotsDistribution> = {
  uniform: TexturedDotsDistribution.Uniform,
  normal: TexturedDotsDistribution.Normal,
  exp: TexturedDotsDistribution.Exponential,
  rexp: TexturedDotsDistribution.ReverseExponential
}
for (const [name, expected] of Object.entries(texturedExpected)) {
  const dots = generateTexturedDots(texturedPath, makeTexturedOptions(distributionMap[name]))
  if (dots.length !== 150) throw new Error(`textured ${name}: ${dots.length} dots, expected 150`)
  for (let i = 0; i < 8; i++) {
    const d = dots[i]
    approx(d.x, expected.rows[i][0], `textured ${name}[${i}].x`)
    approx(d.y, expected.y[i], `textured ${name}[${i}].y`)
    approx(d.rot, expected.rows[i][1], `textured ${name}[${i}].rot`)
    approx(d.rx, expected.rows[i][2], `textured ${name}[${i}].rx`)
    if (d.ry !== d.rx) throw new Error(`textured ${name}[${i}]: circle ry must equal rx`)
  }
}

